from .base import BaseInterface
from ..toollogparser import ToolLogParser


class FileOperations(BaseInterface):

    def request_should_be_sent_from_sem_to_bts(self, req_type, filepath=None, filename='Tool.log', occurrence=1, **kwargs):
        """
        Checks if a message of req_type was sent
        :param string  req_type    The message sent from the SEM to the BTS/TRS
        :param string  filename    File name of logfile produced by the CommandLineTools. Defaults to Tool.log
        :param integer occurrence  The originality of the req_type message sent. Defaults to 1 (1st instance of the req_type message)
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        filename = filename.strip()
        occurrence = occurrence or 1
        config = self.command_store.get(alias=alias).get_config()
        filepath = filepath if filepath else config.log_path

        tool_log_parser = ToolLogParser(filepath, filename)
        tool_log_parser.request_should_be_sent_from_sem_to_bts(req_type, occurrence)

    def a_response_for_request_should_be(self, req_type, response, filepath=None, filename='Tool.log', occurrence=1, **kwargs):
        """
        Checks if the response is received by SEM

        :param string  req_type    The message sent from the SEM to the BTS/TRS
        :param string  response    The message received by SEM
        :param string  filename    File name of logfile produced by the CommandLineTools. Defaults to Tool.log
        :param integer occurrence  The originality of the req_type message sent. Defaults to 1 (1st instance of the req_type message)
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        filename = filename.strip()
        occurrence = occurrence or 1
        config = self.command_store.get(alias=alias).get_config()
        filepath = filepath if filepath else config.log_path

        tool_log_parser = ToolLogParser(filepath, filename)
        tool_log_parser.a_response_for_request_should_be(req_type, occurrence, response)

    def all_responses_for_request_should_be(self, req_type, filepath=None, filename='Tool.log', occurrence=1, responses=None, **kwargs):
        """
        Checks if all responses sent by BTS to the SEM is the set of messages defined by *responses

        :param string  req_type    The message sent from the SEM to the BTS/TRS
        :param string  responses   List containing ALL responses sent by BTS to SEM
        :param string  filename    File name of logfile produced by the CommandLineTools. Defaults to Tool.log
        :param integer occurrence  The originality of the req_type message sent. Defaults to 1 (1st instance of the req_type message)
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias=alias).get_config()
        filepath = filepath if filepath else config.log_path

        tool_log_parser = ToolLogParser(filepath, filename)
        tool_log_parser.all_responses_for_request_should_be(req_type, occurrence, responses)
